for r in range(14,26):
    row=[]
    for c in range(1,15):
        row.append(ws.cell(row=r,column=c).value)
    print(r,row)

# Find year-like values in first 60 rows, columns A-N
import re
years=[]
for r in range(1,61):
    for c in range(1,15):
        v=ws.cell(row=r,column=c).value
        if isinstance(v,int) and 1900< v < 2100:
            years.append((r,c,v))
        elif isinstance(v,str) and re.fullmatch(r'20\d{2}', v.strip()):
            years.append((r,c,int(v.strip())))
print('\nYear-like cells found:', years[:40], '... total', len(years))

wst=wb['Task']
print('\nTask rows 8-33 cols A-M non-empty cells:')
for r in range(8,34):
    items=[]
    for c in range(1,14):
        v=wst.cell(row=r,column=c).value
        if v is not None and str(v).strip()!='':
            items.append((f'{get_column_letter(c)}{r}', v))
    if items:
        print('Row',r, items)

print('\nTask rows 33-55 cols A-M non-empty cells:')
